style.css:
@-moz-document domain("chat.openai.com"), domain("chatgpt.com") {
/* ? Pastel Pink ChatGPT Theme ? */

/* Page background */
body {
  background-color: #fff0f6 !important;
}

/* Main chat area */
div[class*="chat"] {
  background-color: #ffe4f0 !important;
}

/* User message bubbles */
div[class*="user"] {
  background-color: #ffd6eb !important;
  color: #5c2a45 !important;
  border-radius: 18px !important;
}

/* Assistant message bubbles */
div[class*="assistant"] {
  background-color: #fff5fa !important;
  color: #5c2a45 !important;
  border-radius: 18px !important;
}

/* Input box */
textarea, input {
  background-color: #ffeaf4 !important;
  color: #5c2a45 !important;
  border: 1px solid #ffc2dd !important;
  border-radius: 14px !important;
}

/* Buttons */
button {
  background-color: #ffb6d9 !important;
  color: #5c2a45 !important;
  border-radius: 14px !important;
  border: none !important;
}

button:hover {
  background-color: #ffa6cf !important;
}

/* Scrollbar */
::-webkit-scrollbar-thumb {
  background: #ffcae6;
  border-radius: 10px;
}
}
